INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000059','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Mon employeur me doit du salaire en retard. Que faire ?','Réclamer par écrit (lettre recommandée). En cas de refus, saisir l''inspection du travail puis les prud''hommes. On peut aussi faire un signalement à l''URSSAF si la situation se prolonge.','true','2026-05-27 17:40:30.108699+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000005a','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Je veux comprendre la mutuelle d''entreprise. Est-elle obligatoire ?','Depuis 2016, l''employeur du privé doit proposer une complémentaire santé (mutuelle) à tous ses salariés et prendre en charge au moins 50% de la cotisation. Le salarié peut parfois en être dispensé.','true','2026-05-27 17:40:30.108699+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000005b','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Je veux scolariser mon enfant en milieu d''année. Est-ce possible ?','Oui. Une scolarisation en cours d''année est possible (déménagement, arrivée en France). Il faut s''adresser à la mairie. L''enfant est accueilli à l''école de secteur. Des dispositifs UPE2A existent pour les non francophones.','true','2026-05-27 17:40:30.108699+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000005c','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Je veux savoir comment fonctionne le RSA. Qui peut en bénéficier ?','Le RSA est ouvert aux personnes de 25 ans et plus (ou 18-24 ans sous conditions) qui résident en France de manière stable, avec des revenus en dessous d''un certain plafond. La CAF l''examine.','true','2026-05-27 17:40:30.108699+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000005d','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Quels sont les critères pour obtenir la nationalité française par naturalisation ?','Pour la naturalisation : être majeur, justifier d''un séjour régulier en France (5 ans en général), maîtriser le français (niveau B2), connaître l''histoire/culture/société française, avoir des ressources, ne pas avoir de condamnation grave, adhérer aux valeurs républicaines.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000005e','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne le ''droit du sol'' en droit français ?','Le droit du sol attribue automatiquement la nationalité française à un enfant né en France de parents étrangers, sous certaines conditions de résidence en France à sa majorité.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000005f','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne le ''droit du sang'' en droit français ?','Le droit du sang attribue la nationalité française à un enfant si l''un de ses parents (au moins) est français, quel que soit le lieu de naissance.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000060','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Quelle cérémonie marque l''obtention de la nationalité française par naturalisation ?','Une cérémonie d''accueil dans la citoyenneté française est organisée en préfecture. Les nouveaux Français y reçoivent leur décret de naturalisation et la Charte des droits et devoirs du citoyen français.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000061','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne la ''déclaration de nationalité française'' après un mariage ?','Un étranger marié à un Français peut acquérir la nationalité française par déclaration après 4 ans de mariage (5 si la communauté de vie n''a pas commencé en France ou si l''époux ne réside pas en France).','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000062','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne la ''double nationalité'' en droit français ?','La France autorise la double (ou multiple) nationalité : un Français peut conserver ou acquérir une autre nationalité. Tous les pays ne l''autorisent pas (certains exigent de renoncer à la nationalité d''origine).','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000063','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Comment un mineur étranger né en France acquiert-il la nationalité française ?','L''enfant né en France de parents étrangers acquiert automatiquement la nationalité française à sa majorité, s''il réside en France depuis l''âge de 11 ans (au moins 5 ans). Peut être anticipée dès 13 ans.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000064','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne l''OFPRA ?','L''Office français de protection des réfugiés et apatrides examine les demandes d''asile et accorde le statut de réfugié ou la protection subsidiaire en France.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000065','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Quelle est la différence entre ''statut de réfugié'' et ''protection subsidiaire'' ?','Le statut de réfugié est accordé aux personnes persécutées pour leurs convictions (Convention de Genève, 1951). La protection subsidiaire concerne ceux exposés à un risque grave (peine de mort, torture, conflit armé) sans rentrer dans la Convention de Genève.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000066','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Quelle institution européenne assure les politiques migratoires communes ?','L''agence européenne Frontex coordonne la gestion des frontières extérieures de l''UE. L''EASO (devenue EUAA) coordonne les politiques d''asile entre États membres.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000067','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que prévoit le règlement Dublin pour les demandeurs d''asile en Europe ?','Le règlement Dublin détermine quel État membre est responsable de l''examen d''une demande d''asile (généralement le premier pays d''entrée). Vise à éviter les demandes multiples et l''''asylum shopping''.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000068','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne la ''CMU-C'' devenue ''C2S'' ?','La Couverture maladie universelle complémentaire (CMU-C), devenue Complémentaire santé solidaire (C2S) en 2019, est une mutuelle gratuite ou peu chère pour les personnes à faibles revenus.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000069','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne l''AME (Aide médicale d''État) ?','L''AME permet aux étrangers en situation irrégulière résidant en France depuis 3 mois et à faibles revenus de bénéficier d''une prise en charge des frais de santé.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000006a','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne le RSA-Jeunes en France ?','Le RSA-Jeunes est une variante du RSA pour les 18-24 ans, accessible sous des conditions strictes (avoir travaillé 2 ans sur les 3 dernières années). Le contrat d''engagement jeune (CEJ) le complète.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000006b','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne l''allocation aux adultes handicapés (AAH) ?','L''AAH est versée aux personnes handicapées (taux >= 80% ou 50-79% avec restriction d''emploi) dont les revenus sont en dessous d''un plafond. Elle compense les difficultés liées au handicap.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000006c','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne la MDPH ?','La Maison départementale des personnes handicapées (MDPH) est le guichet unique départemental pour toutes les demandes des personnes handicapées : allocations, cartes, orientation, scolarisation.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000006d','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Quel sigle désigne l''organisme qui certifie le niveau de français des candidats à la nationalité ?','Le TCF (Test de connaissance du français) et le DELF/DALF sont des tests reconnus pour évaluer le niveau de français. Le TCF Intégration, Résident, Naturalité (IRN) est spécifiquement adapté.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000006e','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne l''examen civique obligatoire pour la naturalisation depuis 2026 ?','Depuis le 1er janvier 2026, les candidats au CSP, CR ou à la naturalisation doivent réussir un examen civique (QCM de 40 questions, 32 bonnes réponses minimum) sur la France et ses valeurs.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000006f','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Quelles sont les valeurs républicaines auxquelles le nouveau Français doit adhérer ?','Les valeurs républicaines : Liberté, Égalité, Fraternité, Laïcité, Démocratie, État de droit, respect des autres, séparation des pouvoirs, égalité femmes-hommes, refus des violences et discriminations.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000070','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne la ''Charte des droits et devoirs du citoyen français'' ?','Document remis aux nouveaux Français lors de la cérémonie de naturalisation, il rappelle les valeurs, droits et devoirs essentiels du citoyen français. Signé par le candidat.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000071','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Le mariage en France implique-t-il les mêmes droits pour les deux conjoints ?','Oui. Depuis 1970 (puis renforcements ultérieurs), les conjoints sont égaux en droits et devoirs. Plus aucune notion de ''chef de famille''.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000072','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Quel événement marque l''inscription de l''IVG dans la Constitution ?','Le 8 mars 2024 (Journée internationale des droits des femmes), la France est devenue le premier pays au monde à inscrire la liberté de recourir à l''IVG dans sa Constitution.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000073','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Quel est le délai légal pour l''IVG en France ?','L''IVG est légale jusqu''à 14 semaines de grossesse (16 semaines d''aménorrhée), suite à la loi du 2 mars 2022 qui a allongé le délai de 12 à 14 semaines.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000074','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Quel principe encadre la gestation pour autrui (GPA) en France ?','La GPA (gestation pour autrui, c''est-à-dire les mères porteuses) est interdite en France au nom du principe d''indisponibilité du corps humain. Une convention GPA est nulle.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000075','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','La PMA (procréation médicalement assistée) est-elle ouverte à toutes les femmes en France ?','Depuis la loi de bioéthique du 2 août 2021, la PMA est ouverte aux couples de femmes et aux femmes seules, en plus des couples hétérosexuels. Elle est prise en charge par la Sécurité sociale.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000076','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Quel âge impose le mariage civil en France ?','L''âge minimum pour se marier est de 18 ans. Une dispense exceptionnelle peut être accordée par le procureur pour motifs graves (rare en pratique). Le mariage de mineur est très encadré.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000077','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Quel principe régit le partage des biens dans le mariage par défaut en France ?','Par défaut, les époux sont sous le régime de la communauté réduite aux acquêts : les biens acquis pendant le mariage sont communs, les biens d''avant et les héritages sont propres. D''autres régimes existent (séparation, communauté universelle).','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000078','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne la ''réserve héréditaire'' en droit français ?','La réserve héréditaire est la part du patrimoine réservée aux héritiers réservataires (enfants principalement). On ne peut pas les déshériter complètement par testament.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000079','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Quel âge permet d''être électeur en France ?','Il faut avoir 18 ans (majorité civique) pour pouvoir voter en France, sous condition d''être français (sauf élections européennes/municipales pour les ressortissants UE) et inscrit sur les listes électorales.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000007a','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne le ''permis de conduire à points'' français ?','Le permis de conduire français est doté de 12 points (6 pour les nouveaux conducteurs pendant 3 ans). Les infractions retirent des points. La perte totale entraîne l''invalidation.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000007b','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne l''AGS (Association pour la gestion du régime de garantie des salaires) ?','L''AGS garantit le paiement des salaires des employés en cas de faillite de leur employeur. Elle est financée par une cotisation patronale obligatoire.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000007c','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','CONNAISSANCE','Que désigne le ''CSE'' depuis 2017 ?','Le Comité social et économique (CSE) a remplacé les anciennes instances représentatives du personnel (DP, CE, CHSCT) depuis 2017 (entrée en vigueur progressive jusqu''en 2020). Une seule instance unique.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000007d','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','MISE_SITUATION','Je veux déposer une demande de naturalisation française. Quelles sont les principales étapes ?','1. Vérifier l''éligibilité (5 ans de résidence régulière, niveau B2, intégration). 2. Réunir le dossier (état civil, fiches d''imposition, justificatifs). 3. Déposer en ligne. 4. Examen civique. 5. Entretien d''assimilation. 6. Décret de naturalisation et cérémonie.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000007e','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','MISE_SITUATION','Je passe l''examen civique pour ma naturalisation. Quel score minimum ?','Il faut obtenir au moins 32 réponses correctes sur 40 (80%) pour réussir l''examen civique introduit par le décret du 1er janvier 2026.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-00000000007f','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','MISE_SITUATION','Je veux préparer la cérémonie d''accueil dans la citoyenneté française. À quoi m''attendre ?','Réception officielle en préfecture en présence du préfet ou du maire. Remise du décret de naturalisation et de la Charte des droits et devoirs. Souvent moment d''émotion et de solennité, avec Marseillaise et symboles républicains.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000080','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','MISE_SITUATION','Je découvre que je peux perdre la nationalité française. Dans quels cas ?','La nationalité française peut être retirée en cas de fraude lors de l''acquisition (dans les 2 ans). La déchéance (rare) frappe ceux condamnés pour terrorisme/crimes graves contre la nation, et binationaux ayant acquis la nationalité française.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000081','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','MISE_SITUATION','Je veux comprendre l''impact d''un casier judiciaire sur ma demande de nationalité. Quels repères ?','Toute condamnation à au moins 6 mois de prison ferme rend en principe la naturalisation impossible (sauf réhabilitation). Une condamnation pour terrorisme ou crime contre les intérêts de la nation est un obstacle absolu.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000082','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','MISE_SITUATION','Je veux faire reconnaître mes diplômes étrangers en France. À qui m''adresser ?','Le Centre ENIC-NARIC (au sein de France Éducation international) délivre une attestation de comparabilité des diplômes étrangers. Cela facilite l''inscription à une formation ou un emploi.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000083','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','MISE_SITUATION','Je veux comprendre la différence entre nationalité et citoyenneté. Quelle distinction ?','La nationalité est le lien juridique d''une personne avec un État. La citoyenneté est le statut conférant des droits politiques (vote, éligibilité). En France, citoyenneté et nationalité sont généralement liées pour les Français.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000084','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','MISE_SITUATION','Je viens d''obtenir la nationalité française. Quels droits nouveaux ?','Le droit de vote à toutes les élections (présidentielle, législatives, etc.), l''éligibilité à tous les mandats électifs, l''accès aux emplois publics réservés aux Français, la protection consulaire française à l''étranger.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000085','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','MISE_SITUATION','Je veux comprendre ce qu''implique ''l''assimilation à la communauté française'' lors de l''examen pour la nationalité.','L''entretien d''assimilation évalue : connaissance de l''histoire/culture française, adhésion aux valeurs républicaines (laïcité, égalité F/H), maîtrise de la langue, intégration sociale et professionnelle, absence de polygamie.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-000000000086','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'NAT','MISE_SITUATION','Je veux comprendre pourquoi la laïcité est si centrale en France. Quels repères ?','La laïcité est issue de la loi de 1905 (séparation des Églises et de l''État) et est inscrite dans la Constitution (article 1er). Elle garantit la liberté de conscience, la neutralité religieuse de l''État, et l''égalité des citoyens.','true','2026-05-27 17:40:30.128245+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-0000000000e1','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Que désigne la ''prime d''activité'' ?','La prime d''activité est versée par la CAF aux travailleurs (salariés ou indépendants) aux faibles revenus, pour compléter leur rémunération et inciter au travail.','true','2026-05-27 17:40:30.108699+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-0000000000e2','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Qu''est-ce qu''un dossier de surendettement ?','Le dossier de surendettement, déposé à la Banque de France, est ouvert aux particuliers qui ne peuvent plus rembourser leurs dettes. Une commission examine et peut proposer un plan d''apurement ou un effacement.','true','2026-05-27 17:40:30.108699+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-0000000000e3','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Qu''est-ce qu''une convention collective ?','Une convention collective est un accord conclu entre syndicats de salariés et organisations patronales d''un secteur. Elle complète le Code du travail (salaires minimaux, congés, primes...).','true','2026-05-27 17:40:30.108699+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000002-0000-0000-0000-0000000000e4','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','À qui s''adresse un demandeur d''asile en France ?','Le demandeur d''asile doit s''adresser à la GUDA (guichet unique demandeur d''asile) puis à l''OFPRA, qui examine la demande de protection internationale (statut de réfugié, protection subsidiaire).','true','2026-05-27 17:40:30.108699+02',NULL,'ACTIVE',NULL,NULL,NULL);
